97|		}
98|
99|		++*in_pos;
100|		break;
101|
102|	case SEQ_UNCOMPRESSED_SIZE:
103|		coder->uncompressed_size
104|				|= (lzma_vli)(in[*in_pos]) << (coder->pos * 8);
105|		++*in_pos;
