806|static enum coder_init_ret
807|coder_init(file_pair *pair)
808|{
809|	lzma_ret ret = LZMA_PROG_ERROR;
810|
811|	// In most cases if there is input left when coding finishes,
812|	// something has gone wrong. Exceptions are --single-stream
813|	// and decoding .lz files which can contain trailing non-.lz data.
814|	// These will be handled later in this function.
815|	allow_trailing_input = false;
816|
817|	// Set the first filter chain. If the --block-list option is not
818|	// used then use the default filter chain (chains[0]).
819|	// Otherwise, use first filter chain from the block list.
820|	lzma_filter *active_filters = opt_block_list == NULL
821|			? chains[0]
822|			: chains[opt_block_list[0].chain_num];
823|
824|	if (opt_mode == MODE_COMPRESS) {
825|#ifdef HAVE_ENCODERS
826|		switch (opt_format) {
827|		case FORMAT_AUTO:
828|			// args.c ensures this.
829|			assert(0);
830|			break;
831|
832|		case FORMAT_XZ:
833|#	ifdef MYTHREAD_ENABLED
834|			mt_options.filters = active_filters;
835|			if (hardware_threads_is_mt())
836|				ret = lzma_stream_encoder_mt(
837|						&strm, &mt_options);
838|			else
839|#	endif
840|				ret = lzma_stream_encoder(
841|						&strm, active_filters, check);
842|			break;
843|
844|		case FORMAT_LZMA:
845|			ret = lzma_alone_encoder(&strm,
846|					active_filters[0].options);
847|			break;
848|
849|#	ifdef HAVE_LZIP_DECODER
850|		case FORMAT_LZIP:
851|			// args.c should disallow this.
852|			assert(0);
853|			ret = LZMA_PROG_ERROR;
854|			break;
855|#	endif
856|
857|		case FORMAT_RAW:
858|			ret = lzma_raw_encoder(&strm, active_filters);
859|			break;
860|		}
861|#endif
862|	} else {
863|#ifdef HAVE_DECODERS
864|		uint32_t flags = 0;
865|
866|		// It seems silly to warn about unsupported check if the
867|		// check won't be verified anyway due to --ignore-check.
868|		if (opt_ignore_check)
869|			flags |= LZMA_IGNORE_CHECK;
870|		else
871|			flags |= LZMA_TELL_UNSUPPORTED_CHECK;
872|
873|		if (opt_single_stream)
874|			allow_trailing_input = true;
875|		else
876|			flags |= LZMA_CONCATENATED;
877|
878|		// We abuse FORMAT_AUTO to indicate unknown file format,
879|		// for which we may consider passthru mode.
880|		enum format_type init_format = FORMAT_AUTO;
881|
882|		switch (opt_format) {
883|		case FORMAT_AUTO:
884|			// .lz is checked before .lzma since .lzma detection
885|			// is more complicated (no magic bytes).
886|			if (is_format_xz())
887|				init_format = FORMAT_XZ;
888|#	ifdef HAVE_LZIP_DECODER
889|			else if (is_format_lzip())
890|				init_format = FORMAT_LZIP;
891|#	endif
892|			else if (is_format_lzma())
893|				init_format = FORMAT_LZMA;
894|			break;
895|
896|		case FORMAT_XZ:
897|			if (is_format_xz())
898|				init_format = FORMAT_XZ;
899|			break;
900|
901|		case FORMAT_LZMA:
902|			if (is_format_lzma())
903|				init_format = FORMAT_LZMA;
904|			break;
905|
906|#	ifdef HAVE_LZIP_DECODER
907|		case FORMAT_LZIP:
908|			if (is_format_lzip())
909|				init_format = FORMAT_LZIP;
910|			break;
911|#	endif
912|
913|		case FORMAT_RAW:
914|			init_format = FORMAT_RAW;
915|			break;
916|		}
917|
918|		switch (init_format) {
919|		case FORMAT_AUTO:
920|			// Unknown file format. If --decompress --stdout
921|			// --force have been given, then we copy the input
922|			// as is to stdout. Checking for MODE_DECOMPRESS
923|			// is needed, because we don't want to do use
924|			// passthru mode with --test.
925|			if (opt_mode == MODE_DECOMPRESS
926|					&& opt_stdout && opt_force) {
927|				// These are needed for progress info.
928|				strm.total_in = 0;
929|				strm.total_out = 0;
930|				return CODER_INIT_PASSTHRU;
931|			}
932|
933|			ret = LZMA_FORMAT_ERROR;
934|			break;
935|
936|		case FORMAT_XZ:
937|#	ifdef MYTHREAD_ENABLED
938|			mt_options.flags = flags;
939|
940|			mt_options.threads = hardware_threads_get();
941|			mt_options.memlimit_stop
942|				= hardware_memlimit_get(MODE_DECOMPRESS);
943|
944|			// If single-threaded mode was requested, set the
945|			// memlimit for threading to zero. This forces the
946|			// decoder to use single-threaded mode which matches
947|			// the behavior of lzma_stream_decoder().
948|			//
949|			// Otherwise use the limit for threaded decompression
950|			// which has a sane default (users are still free to
951|			// make it insanely high though).
952|			mt_options.memlimit_threading
953|					= mt_options.threads == 1
954|					? 0 : hardware_memlimit_mtdec_get();
955|
956|			ret = lzma_stream_decoder_mt(&strm, &mt_options);
957|#	else
958|			ret = lzma_stream_decoder(&strm,
959|					hardware_memlimit_get(
960|						MODE_DECOMPRESS), flags);
961|#	endif
962|			break;
963|
964|		case FORMAT_LZMA:
965|			ret = lzma_alone_decoder(&strm,
966|					hardware_memlimit_get(
967|						MODE_DECOMPRESS));
968|			break;
969|
970|#	ifdef HAVE_LZIP_DECODER
971|		case FORMAT_LZIP:
972|			allow_trailing_input = true;
973|			ret = lzma_lzip_decoder(&strm,
974|					hardware_memlimit_get(
975|						MODE_DECOMPRESS), flags);
976|			break;
977|#	endif
978|
979|		case FORMAT_RAW:
980|			// Memory usage has already been checked in
981|			// coder_set_compression_settings().
982|			ret = lzma_raw_decoder(&strm, active_filters);
983|			break;
984|		}
985|
986|		// Try to decode the headers. This will catch too low
987|		// memory usage limit in case it happens in the first
988|		// Block of the first Stream, which is where it very
989|		// probably will happen if it is going to happen.
990|		//
991|		// This will also catch unsupported check type which
992|		// we treat as a warning only. If there are empty
993|		// concatenated Streams with unsupported check type then
994|		// the message can be shown more than once here. The loop
995|		// is used in case there is first a warning about
996|		// unsupported check type and then the first Block
997|		// would exceed the memlimit.
998|		if (ret == LZMA_OK && init_format != FORMAT_RAW) {
999|			strm.next_out = NULL;
1000|			strm.avail_out = 0;
1001|			while ((ret = lzma_code(&strm, LZMA_RUN))
1002|					== LZMA_UNSUPPORTED_CHECK)
1003|				message_warning(_("%s: %s"),
1004|					tuklib_mask_nonprint(pair->src_name),
1005|					message_strm(ret));
1006|
1007|			// With --single-stream lzma_code won't wait for
1008|			// LZMA_FINISH and thus it can return LZMA_STREAM_END
1009|			// if the file has no uncompressed data inside.
1010|			// So treat LZMA_STREAM_END as LZMA_OK here.
1011|			// When lzma_code() is called again in coder_normal()
1012|			// it will return LZMA_STREAM_END again.
1013|			if (ret == LZMA_STREAM_END)
1014|				ret = LZMA_OK;
1015|		}
1016|#endif
1017|	}
1018|
1019|	if (ret != LZMA_OK) {
1020|		message_error(_("%s: %s"),
1021|				tuklib_mask_nonprint(pair->src_name),
1022|				message_strm(ret));
1023|		if (ret == LZMA_MEMLIMIT_ERROR)
1024|			message_mem_needed(V_ERROR, lzma_memusage(&strm));
1025|
1026|		return CODER_INIT_ERROR;
1027|	}
1028|
1029|	return CODER_INIT_NORMAL;
1030|}

168|static void
169|uncompress(lzma_stream *strm, FILE *file, const char *filename)
170|{
171|	lzma_ret ret;
172|
173|	// Initialize the decoder
174|#ifdef LZMADEC
175|	ret = lzma_alone_decoder(strm, UINT64_MAX);
176|#else
177|	ret = lzma_stream_decoder(strm, UINT64_MAX, LZMA_CONCATENATED);
178|#endif
179|
180|	// The only reasonable error here is LZMA_MEM_ERROR.
181|	if (ret != LZMA_OK) {
182|		my_errorf("%s", ret == LZMA_MEM_ERROR ? strerror(ENOMEM)
183|				: "Internal error (bug)");
184|		exit(EXIT_FAILURE);
185|	}
186|
187|	// Input and output buffers
188|	uint8_t in_buf[BUFSIZ];
189|	uint8_t out_buf[BUFSIZ];
190|
191|	strm->avail_in = 0;
192|	strm->next_out = out_buf;
193|	strm->avail_out = BUFSIZ;
194|
195|	lzma_action action = LZMA_RUN;
196|
197|	while (true) {
198|		if (strm->avail_in == 0) {
199|			strm->next_in = in_buf;
200|			strm->avail_in = fread(in_buf, 1, BUFSIZ, file);
201|
202|			if (ferror(file)) {
203|				// POSIX says that fread() sets errno if
204|				// an error occurred. ferror() doesn't
205|				// touch errno.
206|				my_errorf("%s: Error reading input file: %s",
207|					tuklib_mask_nonprint(filename),
208|					strerror(errno));
209|				exit(EXIT_FAILURE);
210|			}
211|
212|#ifndef LZMADEC
213|			// When using LZMA_CONCATENATED, we need to tell
214|			// liblzma when it has got all the input.
215|			if (feof(file))
216|				action = LZMA_FINISH;
217|#endif
218|		}
219|
220|		ret = lzma_code(strm, action);
221|
222|		// Write and check write error before checking decoder error.
223|		// This way as much data as possible gets written to output
224|		// even if decoder detected an error.
225|		if (strm->avail_out == 0 || ret != LZMA_OK) {
226|			const size_t write_size = BUFSIZ - strm->avail_out;
227|
228|			if (fwrite(out_buf, 1, write_size, stdout)
229|					!= write_size) {
230|				// Wouldn't be a surprise if writing to stderr
231|				// would fail too but at least try to show an
232|				// error message.
233|#if defined(_WIN32) && !defined(__CYGWIN__)
234|				// On native Windows, broken pipe is reported
235|				// as EINVAL. Don't show an error message
236|				// in this case.
237|				if (errno != EINVAL)
238|#endif
239|				{
240|					my_errorf("Cannot write to "
241|						"standard output: "
242|						"%s", strerror(errno));
243|				}
244|				exit(EXIT_FAILURE);
245|			}
246|
247|			strm->next_out = out_buf;
248|			strm->avail_out = BUFSIZ;
249|		}
250|
251|		if (ret != LZMA_OK) {
252|			if (ret == LZMA_STREAM_END) {
253|#ifdef LZMADEC
254|				// Check that there's no trailing garbage.
255|				if (strm->avail_in != 0
256|						|| fread(in_buf, 1, 1, file)
257|							!= 0
258|						|| !feof(file))
259|					ret = LZMA_DATA_ERROR;
260|				else
261|					return;
262|#else
263|				// lzma_stream_decoder() already guarantees
264|				// that there's no trailing garbage.
265|				assert(strm->avail_in == 0);
266|				assert(action == LZMA_FINISH);
267|				assert(feof(file));
268|				return;
269|#endif
270|			}
271|
272|			const char *msg;
273|			switch (ret) {
274|			case LZMA_MEM_ERROR:
275|				msg = strerror(ENOMEM);
276|				break;
277|
278|			case LZMA_FORMAT_ERROR:
279|				msg = "File format not recognized";
280|				break;
281|
282|			case LZMA_OPTIONS_ERROR:
283|				// FIXME: Better message?
284|				msg = "Unsupported compression options";
285|				break;
286|
287|			case LZMA_DATA_ERROR:
288|				msg = "File is corrupt";
289|				break;
290|
291|			case LZMA_BUF_ERROR:
292|				msg = "Unexpected end of input";
293|				break;
294|
295|			default:
296|				msg = "Internal error (bug)";
297|				break;
298|			}
299|
300|			my_errorf("%s: %s", tuklib_mask_nonprint(filename),
301|					msg);
302|			exit(EXIT_FAILURE);
303|		}
304|	}
305|}

20|extern int
21|LLVMFuzzerTestOneInput(const uint8_t *inbuf, size_t inbuf_size)
22|{
23|	lzma_stream strm = LZMA_STREAM_INIT;
24|	// Initialize a LZMA alone decoder using the memory usage limit
25|	// defined in fuzz_common.h
26|	lzma_ret ret = lzma_alone_decoder(&strm, MEM_LIMIT);
27|
28|	if (ret != LZMA_OK) {
29|		// This should never happen unless the system has
30|		// no free memory or address space to allow the small
31|		// allocations that the initialization requires.
32|		fprintf(stderr, "lzma_alone_decoder() failed (%d)\n", ret);
33|		abort();
34|	}
35|
36|	fuzz_code(&strm, inbuf, inbuf_size);
37|
38|	// Free the allocated memory.
39|	lzma_end(&strm);
40|	return 0;
41|}

98|static void
99|test_memlimit_alone_decoder(void)
100|{
101|#ifndef HAVE_DECODERS
102|	assert_skip("Decoder support disabled");
103|#else
104|	size_t alone_size;
105|	uint8_t *alone_buf = tuktest_file_from_srcdir(
106|			"files/good-unknown_size-with_eopm.lzma", &alone_size);
107|
108|	lzma_stream strm = LZMA_STREAM_INIT;
109|	assert_lzma_ret(lzma_alone_decoder(&strm, MEMLIMIT_TOO_LOW), LZMA_OK);
110|
111|	strm.next_in = alone_buf;
112|	strm.avail_in = alone_size;
113|	strm.next_out = out;
114|	strm.avail_out = sizeof(out);
115|
116|	assert_lzma_ret(lzma_code(&strm, LZMA_FINISH), LZMA_MEMLIMIT_ERROR);
117|
118|	assert_uint_eq(lzma_memlimit_get(&strm), MEMLIMIT_TOO_LOW);
119|	assert_lzma_ret(lzma_memlimit_set(&strm, MEMLIMIT_TOO_LOW + 1),
120|			LZMA_MEMLIMIT_ERROR);
121|	assert_lzma_ret(lzma_memlimit_set(&strm, MEMLIMIT_HIGH_ENOUGH),
122|			LZMA_OK);
123|
124|	assert_lzma_ret(lzma_code(&strm, LZMA_FINISH), LZMA_STREAM_END);
125|	lzma_end(&strm);
126|#endif
127|}

164|static lzma_ret
165|auto_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
166|		uint64_t memlimit, uint32_t flags)
167|{
168|	lzma_next_coder_init(&auto_decoder_init, next, allocator);
169|
170|	if (flags & ~LZMA_SUPPORTED_FLAGS)
171|		return LZMA_OPTIONS_ERROR;
172|
173|	lzma_auto_coder *coder = next->coder;
174|	if (coder == NULL) {
175|		coder = lzma_alloc(sizeof(lzma_auto_coder), allocator);
176|		if (coder == NULL)
177|			return LZMA_MEM_ERROR;
178|
179|		next->coder = coder;
180|		next->code = &auto_decode;
181|		next->end = &auto_decoder_end;
182|		next->get_check = &auto_decoder_get_check;
183|		next->memconfig = &auto_decoder_memconfig;
184|		coder->next = LZMA_NEXT_CODER_INIT;
185|	}
186|
187|	coder->memlimit = my_max(1, memlimit);
188|	coder->flags = flags;
189|	coder->sequence = SEQ_INIT;
190|
191|	return LZMA_OK;
192|}

